const payload = items[0].json || {};
const piiKeys = ['nik', 'no_ktp', 'email', 'phone', 'alamat', 'address', 'suspect_name', 'penggugat', 'tergugat'];
const mask = (value) => typeof value === 'string' ? value.replace(/.(?=.{4})/g, '*') : value;
const sanitize = (obj) => {
  if (!obj || typeof obj !== 'object') return obj;
  const clone = Array.isArray(obj) ? [] : {};
  for (const key of Object.keys(obj)) {
    const val = obj[key];
    clone[key] = piiKeys.includes(key) ? mask(val) : sanitize(val);
  }
  return clone;
};
return [{ json: { error: payload.error, context: sanitize(payload) } }];
